require_relative "test_helper"

class GeneratorTest < Minitest::Test
  include SpecFiles

  def generate(yaml)
    TweakDock::Generator.new(load_spec(yaml)).swift
  end

  def test_writes_a_tweak_for_each_experiment
    swift = generate(<<~YAML)
      output: Experiments.swift
      store: .experiments
      experiments:
        exp_paywall: [A, B, C]
    YAML

    assert_equal <<~SWIFT, swift
      // Generated by tweakdock from Experiments.yml. Do not edit.

      import TweakDock

      @Tweaks(store: .experiments)
      enum Experiments {
          enum ExpPaywall: String, CaseIterable, TweakValue {
              case A, B, C
          }

          @Tweak(
              collection: "Experiments",
              group: "A/B Tests",
              name: "exp_paywall",
              defaultValue: ExpPaywall.A,
              from: .experiment("exp_paywall")
          )
          static var expPaywall: ExpPaywall
      }
    SWIFT
  end

  def test_writes_the_devices
    swift = generate(<<~YAML)
      output: E.swift
      experiments:
        exp_pad: {variants: [A], devices: pad}
        exp_desktop: {variants: [A], devices: [mac, pad]}
    YAML

    assert_includes swift, "@Tweaks\nenum Experiments {"
    assert_includes swift, 'from: .experiment("exp_pad", devices: .pad)'
    assert_includes swift, 'from: .experiment("exp_desktop", devices: [.pad, .mac])'
  end

  def test_makes_declarations_public
    swift = generate("output: E.swift\naccess: public\nexperiments:\n  exp: [A]\n")

    assert_includes swift, "public enum Experiments {"
    assert_includes swift, "    public enum Exp: String, CaseIterable, TweakValue {"
    assert_includes swift, "    public static var exp: Exp"
  end

  def test_escapes_swift_keywords_and_strings
    swift = generate(<<~YAML)
      output: E.swift
      group: 'Say "hi" \\ bye'
      experiments:
        exp: {variants: [control, default], default: default}
    YAML

    assert_includes swift, "case control, `default`"
    assert_includes swift, "defaultValue: Exp.`default`"
    assert_includes swift, 'group: "Say \"hi\" \\\\ bye"'
  end
end
